#include <iostream>
using namespace std;

bool isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; ++i)
        if (n % i == 0) return false;
    return true;
}

int main() {
    int a, b;
    cin >> a >> b;

    int next = a + 1;
    while (!isPrime(next))
        ++next;

    cout << (next == b ? "YES" : "NO");
    return 0;
}

